mapper.select:
select count(id)
from group_buy_order_list
where activity_id = #{activityId}
  and user_id = #{userId}
  and status in (0, 1)

mapper.update:
update group_buy_order_list
set status = 2,
    update_time = now()
where user_id = #{userId}
  and out_trade_no = #{outTradeNo}
  and status = #{status}
